/// Process-wide handoff for multithreaded fork: the forking thread (parent),
/// after rebuilding its VM, publishes a clone here so quiesced sibling threads
/// recreate their vCPUs in the same (new) process VM.
#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
type SharedVm = applevisor::vm::VirtualMachineInstance<applevisor::vm::GicDisabled>;

#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
fn rebuilt_vm_cell() -> &'static parking_lot::Mutex<Option<SharedVm>> {
    static CELL: std::sync::OnceLock<parking_lot::Mutex<Option<SharedVm>>> =
        std::sync::OnceLock::new();
    CELL.get_or_init(|| parking_lot::Mutex::new(None))
}

/// Carrier-lifetime HVF VM authority: the ONE `hv_vm_create` per carrier plus
/// the five VM-global control mappings and the mailbox-slot allocator that
/// every container's executors share (`PersistentExecutorSpec`).
///
/// Published by the FIRST root bring-up (`HvfVmState::take_persistent_executor_spec`),
/// consumed by every LATER root bring-up (`HvfVmState::new_with_plan` builds
/// the new container's root inside this VM instead of calling `hv_vm_create`,
/// which would return `HV_BUSY`), and drained exactly once by
/// [`destroy_persistent_vm_at_carrier_exit`]. It is never drained at a
/// container's run terminal: containers come and go inside one VM. Readers
/// still consult [`rebuilt_vm_cell`] first, exactly as
/// `from_persistent_executor_spec` does, so a VM rebuilt after publication
/// supersedes the bundle's handle.
#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
#[derive(Clone)]
enum PersistentCarrierCellEntry {
    Published(PersistentExecutorSpec),
    CreateCleanup {
        custody: std::sync::Arc<CarrierVmCustody>,
        generation: CarrierVmGeneration,
        vcpu_id: Option<applevisor_sys::hv_vcpu_t>,
        raw_vm_destroyed: bool,
    },
}

#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
fn persistent_carrier_cell() -> &'static parking_lot::Mutex<Option<PersistentCarrierCellEntry>> {
    static CELL: std::sync::OnceLock<parking_lot::Mutex<Option<PersistentCarrierCellEntry>>> =
        std::sync::OnceLock::new();
    CELL.get_or_init(|| parking_lot::Mutex::new(None))
}

/// Signalled by `take_persistent_executor_spec` when the first root publishes
/// the carrier bundle; paired with `persistent_carrier_cell`'s mutex.
#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
fn carrier_published() -> &'static parking_lot::Condvar {
    static PUBLISHED: parking_lot::Condvar = parking_lot::Condvar::new();
    &PUBLISHED
}

/// Whether this carrier has already retired the boot loader's eager mmap arena.
///
/// The retirement is a VM-wide `hv_vm_unmap` performed during a container's
/// root bring-up, so it must happen exactly once for the carrier's VM rather
/// than once per container: a second unmap would remove sparse arena pages a
/// sibling container has already faulted in. Carrier scope is the correct
/// scope here — the arena belongs to the VM, not to a Linux process — and is
/// cleared with the VM in `record_vm_released` so a rebuilt VM retires its own
/// fresh eager mapping.
#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
fn carrier_initial_arena_retired() -> &'static std::sync::atomic::AtomicBool {
    static RETIRED: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);
    &RETIRED
}

/// Serializes the "does this carrier own a VM yet?" decision across roots
/// booting at the same time. Held across the FIRST root's `hv_vm_create`, so
/// a second root arriving mid-create observes `carrier_vm_live()` and waits
/// for the published bundle instead of issuing its own `hv_vm_create`
/// (which would return `HV_BUSY`).
#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
fn carrier_root_boot_gate() -> &'static parking_lot::Mutex<()> {
    static GATE: parking_lot::Mutex<()> = parking_lot::Mutex::new(());
    &GATE
}

/// Bound on how long a later root waits for the first root to publish the
/// carrier bundle (publication happens at that root's persistent-lane start,
/// before any guest instruction runs).
#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
const CARRIER_PUBLISH_WAIT: std::time::Duration = std::time::Duration::from_secs(60);

/// Whether this carrier currently owns a live HVF VM. Set on the single create
/// funnel's success (`create_vm_with_admission`), cleared by
/// `record_vm_released` after a successful `hv_vm_destroy`.
#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
static CARRIER_VM_LIVE: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);

/// True while this carrier owns a live HVF VM.
#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
pub fn carrier_vm_live() -> bool {
    CARRIER_VM_LIVE.load(std::sync::atomic::Ordering::Acquire)
}

/// How guest-visible sharing maps onto the host and HVPatch's one VM.
///
/// `ForkSharedAnonymous` deliberately shares only the host backing and explicit
/// fork-child descriptor. It stays in the owning mm's IPA scope and does not
/// acquire shared-file futex identity. `GlobalShared` is the existing shared
/// aperture / MAP_SHARED-file behavior whose IPA is VM-global.
#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
#[allow(dead_code)] // Stage-2 mapping is compiled out by the host-test support feature.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum GuestMappingSharing {
    Private,
    ForkSharedAnonymous,
    GlobalShared,
}

#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
impl GuestMappingSharing {
    fn shares_across_fork(self) -> bool {
        self != Self::Private
    }

    fn uses_global_ipa(self) -> bool {
        self == Self::GlobalShared
    }

    fn has_shared_futex_identity(self) -> bool {
        self != Self::Private
    }
}

/// Process-global registry of dynamic alias mappings, so a vCPU can
/// re-establish one in ITS shared VM after fork dropped it.
///
/// Threads share ONE hv_vm, but `fork()` tears that VM down and rebuilds it from
/// ONLY the forking thread's per-thread `mappings` list (see `HvfInner::fork`).
/// A global-shared alias mapped by a SIBLING thread is therefore lost from the
/// rebuilt VM, and any later access stage-2-faults (the go-build telemetry
/// counter: a counter file `mmap(MAP_SHARED)`'d on one thread, read via LDAR on
/// another after `go` forks `compile`). arm64 HVF has no stage-2 TLB shootdown,
/// so we cannot push the map to siblings eagerly; instead each vCPU LAZILY
/// re-maps on the fault, keyed off this registry.
///
/// Every alias is registered for thread fallback. The sharing classification
/// decides whether its IPA is process-scoped or global and whether fork reuses
/// the backing; those decisions must not be inferred from host `MAP_SHARED`.
/// A high-VA alias's IPA window → host backing, registered PROCESS-GLOBALLY. Two
/// roles: (1) the stage-2 lazy on-fault re-map (a vCPU whose forked VM lost an
/// alias re-establishes it), and (2) the SYSCALL-PATH cross-thread fallback —
/// `mapping_for_range` consults this when a guest buffer lives in a high-VA alias
/// ANOTHER thread mapped (each `HvfInner.mappings` is per-thread; Go's heap arenas
/// are shared across goroutines, so a sibling-mapped arena was invisible to a
/// thread's syscall and EFAULTed). The VA→IPA half is already process-shared
/// (`translate_va` over the Arc-shared page tables); this supplies the IPA→host
/// half. Stores a NON-OWNING raw `host_addr` only (never an OwnedHostMapping), so
/// it never participates in Drop / double-free; the backing's lifetime stays with
/// the owning thread's `mappings` Vec and this entry is removed on `munmap`
/// (`unregister_alias`).
/// A unique monotonic token identifying a container root address space within
/// the carrier.
///
/// This distinguishes private alias ownership across independent containers
/// sharing the single VM carrier, without conflating ownership scope with
/// stage-1 page table root slot allocations. It identifies container instance
/// scope in the VMM layer; it is not a guest PID or a security boundary.
#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq, Ord, PartialOrd, Hash)]
pub struct ContainerRootToken(u64);

#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
impl ContainerRootToken {
    /// The sentinel used by fixtures and by contexts that predate container
    /// minting. Minted tokens never take this value — see [`Self::next`].
    pub const ROOT: Self = Self(1);

    /// Mints a fresh, distinct token for a new container root.
    ///
    /// Starts ABOVE [`Self::ROOT`] deliberately: a minted token that aliased
    /// the sentinel would make the first container's private aliases match
    /// every ROOT-scoped alias again, which is the exact collision this type
    /// exists to remove.
    pub fn next() -> Self {
        static NEXT_ID: std::sync::atomic::AtomicU64 =
            std::sync::atomic::AtomicU64::new(ContainerRootToken::ROOT.0 + 1);
        Self(NEXT_ID.fetch_add(1, std::sync::atomic::Ordering::Relaxed))
    }

    pub fn from_raw(raw: u64) -> Self {
        Self(raw)
    }

    pub fn raw(self) -> u64 {
        self.0
    }
}

#[cfg(not(all(target_os = "macos", target_arch = "aarch64")))]
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq, Ord, PartialOrd, Hash)]
pub struct ContainerRootToken(u64);

#[cfg(not(all(target_os = "macos", target_arch = "aarch64")))]
impl ContainerRootToken {
    pub const ROOT: Self = Self(1);

    pub fn from_raw(raw: u64) -> Self {
        Self(raw)
    }

    pub fn raw(self) -> u64 {
        self.0
    }
}

#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
#[derive(Clone, Copy, Debug, Eq, PartialEq, Ord, PartialOrd)]
enum AliasOwnershipScope {
    /// Alias belongs to the root address space of a specific container in this carrier.
    ContainerRoot(ContainerRootToken),
    /// Alias belongs to exactly one HVPatch address space.  The scope is
    /// rebound in the forked host child when an inherited shared-anonymous
    /// frame is materialized into that child's new mm. The stage-1 root slot
    /// tuple is an ownership token only; guest frames use global IPAs.
    MmRootSlot { base: u64, size: u64 },
    /// Shared-file aliases use the historical VM-global IPA namespace.
    Global,
}

#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
fn alias_ownership_scope(
    sharing: GuestMappingSharing,
    mm_root_slot: Option<(u64, u64)>,
    container_root: ContainerRootToken,
) -> AliasOwnershipScope {
    if sharing.uses_global_ipa() {
        AliasOwnershipScope::Global
    } else if let Some((base, size)) = mm_root_slot {
        AliasOwnershipScope::MmRootSlot { base, size }
    } else {
        AliasOwnershipScope::ContainerRoot(container_root)
    }
}

#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
fn rebind_inherited_alias_to_process(
    mut alias: AliasBacking,
    mm_root_slot: (u64, u64),
) -> AliasBacking {
    alias.ownership_scope = AliasOwnershipScope::MmRootSlot {
        base: mm_root_slot.0,
        size: mm_root_slot.1,
    };
    alias
}

#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct AliasBacking {
    /// Guest VIRTUAL start of the alias (the syscall-path region key).
    start: u64,
    ipa: u64,
    host_addr: usize,
    /// Exact guest-visible VA/IPA extent. This deliberately excludes any
    /// host/HVF granule padding retained by `physical_size` below.
    size: usize,
    /// The whole HVF-granular stage-2 extent retained behind this semantic
    /// fragment. Partial Linux unmaps split only the live fields above; VM
    /// rebuild and frame inventory continue to use this exact physical extent.
    physical_ipa: u64,
    physical_host_addr: usize,
    physical_size: usize,
    perms: u64,
    /// Whether the guest may WRITE the alias (a PROT_READ MAP_SHARED file alias
    /// must EFAULT a syscall write, not SIGBUS the host through the raw pointer).
    guest_writable: bool,
    sharing: GuestMappingSharing,
    ownership_scope: AliasOwnershipScope,
    inventory_backing: InventoryBackingIdentity,
    shared_key_base: u64,
    shared_key_offset: u64,
    /// Which incarnation of the global-frame lease this row was published
    /// against — see [`GlobalFrameHostOwner::generation`]. Without it a row that
    /// outlives its lease silently re-authenticates against the next one.
    owner_generation: u64,
}

#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
fn semantic_extent_size(start: u64, end: u64) -> usize {
    usize::try_from(end.saturating_sub(start)).unwrap_or(usize::MAX)
}

#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
fn split_local_mapping_rows_for_unmap(mappings: &mut Vec<HvfMappedRegion>, va: u64, len: usize) {
    let Some(end) = va.checked_add(len as u64) else {
        return;
    };
    let mut tails = Vec::new();
    for row in mappings.iter_mut() {
        if !row.is_dynamic_alias {
            continue;
        }
        let row_size = semantic_extent_size(row.start, row.end);
        let Some(row_end) = row.start.checked_add(row_size as u64) else {
            continue;
        };
        if row_end <= va || row.start >= end {
            continue;
        }
        let head_survives = row.start < va;
        let tail_survives = row_end > end;
        if !head_survives && !tail_survives {
            continue;
        }
        if tail_survives {
            let delta = end.saturating_sub(row.start);
            tails.push(HvfMappedRegion {
                start: end,
                end: row.end,
                ipa: row.ipa.saturating_add(delta),
                physical_ipa: row.physical_ipa,
                physical_size: row.physical_size,
                host_addr: row.host_addr.wrapping_add(delta as usize),
                size: usize::try_from(row_end.saturating_sub(end)).unwrap_or_default(),
                perms: row.perms,
                memory: None,
                host_mapping: None,
                structural_owner: row.structural_owner.clone(),
                stage2_lease: None,
                is_dynamic_alias: true,
                sharing: row.sharing,
                guest_writable: row.guest_writable,
                shared_key_base: row.shared_key_base,
                shared_key_offset: row.shared_key_offset.saturating_add(delta),
                owner_generation: row.owner_generation,
            });
        }
        if head_survives {
            row.end = va;
            row.size = usize::try_from(va.saturating_sub(row.start)).unwrap_or_default();
        } else {
            // Only the tail survives: advance this row onto it and let the
            // pushed fragment be dropped below.
            let delta = end.saturating_sub(row.start);
            row.ipa = row.ipa.saturating_add(delta);
            row.host_addr = row.host_addr.wrapping_add(delta as usize);
            row.shared_key_offset = row.shared_key_offset.saturating_add(delta);
            row.start = end;
            row.size = usize::try_from(row_end.saturating_sub(end)).unwrap_or_default();
            tails.pop();
        }
    }
    mappings.append(&mut tails);
}

#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
fn is_kernel_only_stage1_range(start: u64, len: usize) -> bool {
    let end = start.saturating_add(len as u64);
    start >= crate::memory::LINUX_KERNEL_REGION_BASE
        && end
            <= crate::memory::LINUX_KERNEL_REGION_BASE
                .saturating_add(carrick_mem::memory::LINUX_KERNEL_REGION_SIZE)
}

// Futex-word keying for `MAP_SHARED` file mappings lives in
// `carrick_host::futex_key` (portable POSIX) so the native (DSR) backend
// derives its waiter keys with the SAME scheme on every host OS. Re-exported
// here because this trap layer is where the keys are consumed on HVF.
#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
pub use carrick_host::futex_key::{shared_file_key_base, shared_futex_waiter_key};

#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
fn alias_registry() -> &'static parking_lot::Mutex<AliasRegistry> {
    static CELL: std::sync::OnceLock<parking_lot::Mutex<AliasRegistry>> =
        std::sync::OnceLock::new();
    CELL.get_or_init(|| parking_lot::Mutex::new(AliasRegistry::default()))
}

/// The carrier-global alias registry, partitioned by owning scope.
///
/// This was a flat `Vec<AliasBacking>`. Because the container is
/// carrier-global but almost every question asked of it is per-process, a
/// guest process exit had to walk every OTHER live process's rows to find its
/// own: measured 2026-08-30 at 45.4% of all carrier user CPU under a
/// fork/exit storm, and O(N^2) across N exiting processes. The address
/// translation path had the same shape — `lookup_shared_alias_by_va` filtered
/// by ownership scope only AFTER scanning the whole registry.
///
/// Rows are grouped by [`AliasOwnershipScope`], which is exactly the axis
/// `alias_is_owned_by_process` selects on, so retirement is a bucket removal.
/// Each row keeps a monotonic insertion sequence so the historical GLOBAL
/// order is still available exactly: several lookups take the LAST matching
/// row, and that must keep meaning "most recently registered", not "in
/// whichever scope happens to sort last".
#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
type AliasExactFirstIndex = std::collections::BTreeMap<
    AliasOwnershipScope,
    std::collections::BTreeMap<(u64, u64), (usize, u64, AliasBacking)>,
>;

#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
#[derive(Debug, Default, Clone)]
struct AliasRegistry {
    by_scope: std::collections::BTreeMap<AliasOwnershipScope, Vec<(u64, AliasBacking)>>,
    /// First row for each exact semantic key inside a scope: bucket position,
    /// insertion sequence and value. Receipt publication asks exactly this
    /// question for every row; locating it through the scope `Vec` made a
    /// k-row publication O(k * rows-in-mm).
    exact_first_by_scope: AliasExactFirstIndex,
    next_seq: u64,
    /// Monotonic semantic-mutation revision used only to prove that a fork
    /// snapshot and delayed retirement observed one coherent alias view.
    revision: u64,
    /// Maintained total of every bucket's length; see [`Self::len`].
    rows: usize,
    /// Rows keyed by guest-VA window start, and by IPA window start.
    ///
    /// Three lookups ask "the row registered LAST whose window contains X"
    /// without a scope to narrow by: `lookup_live_alias_by_va_any_scope`, the
    /// IPA mapping lookup, and the shared-futex location lookup. Answering
    /// those by walking every bucket is O(all live processes) per call on
    /// paths a guest hits per fault and per futex operation — 23.3% of carrier
    /// CPU once the bigger scans were gone. A row can contain X only if it
    /// starts in `[X - widest, X]`, so these turn the walk into a bounded
    /// range query; the exact containment test is unchanged.
    by_va_start: std::collections::BTreeMap<u64, Vec<(u64, AliasBacking)>>,
    by_ipa_start: std::collections::BTreeMap<u64, Vec<(u64, AliasBacking)>>,
    /// Exact physical stage-2 start index used by delayed owner retirement.
    /// The retired owner identity supplies the exact length/host/generation;
    /// this keeps candidate selection O(log n + rows at that physical start)
    /// instead of walking every live process in the carrier.
    by_physical_start: std::collections::BTreeMap<u64, Vec<(u64, AliasBacking)>>,
    /// Per-scope physical stage-2 window index. COW retention asks whether
    /// another semantic VA in this exact mm still projects the source frame;
    /// indexing by `(scope, physical_ipa)` keeps that question bounded to the
    /// two visible scopes and to rows capable of containing the compound.
    by_scope_physical_start:
        std::collections::BTreeMap<(AliasOwnershipScope, u64), Vec<(u64, AliasBacking)>>,
    /// Live physical window sizes per scope. The largest key is the exact
    /// lower-bound radius for that scope's containment query; unlike a global
    /// ever-grown maximum, removing a huge row shrinks the search again and a
    /// foreign process can never widen another mm's lookup.
    physical_size_counts_by_scope:
        std::collections::BTreeMap<AliasOwnershipScope, std::collections::BTreeMap<u64, usize>>,
    /// Widest window ever indexed, per axis. Only ever grows: a stale-wide
    /// bound makes a query walk further than needed, never miss a row.
    widest_va: u64,
    widest_ipa: u64,
}

#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
impl AliasRegistry {
    fn bump_revision(&mut self) {
        self.revision = self.revision.checked_add(1).unwrap_or_else(|| {
            eprintln!("carrick: FATAL: alias registry revision exhausted");
            std::process::abort();
        });
    }

    fn revision(&self) -> u64 {
        self.revision
    }

    fn rebuild_exact_scope(&mut self, scope: AliasOwnershipScope) {
        let Some(rows) = self.by_scope.get(&scope) else {
            self.exact_first_by_scope.remove(&scope);
            return;
        };
        let mut exact = std::collections::BTreeMap::new();
        for (position, &(seq, alias)) in rows.iter().enumerate() {
            exact
                .entry((alias.start, alias.ipa))
                .or_insert((position, seq, alias));
        }
        if exact.is_empty() {
            self.exact_first_by_scope.remove(&scope);
        } else {
            self.exact_first_by_scope.insert(scope, exact);
        }
    }

    fn index_insert(&mut self, seq: u64, alias: AliasBacking) {
        self.by_va_start
            .entry(alias.start)
            .or_default()
            .push((seq, alias));
        self.widest_va = self.widest_va.max(alias.size as u64);
        self.by_ipa_start
            .entry(alias.ipa)
            .or_default()
            .push((seq, alias));
        self.widest_ipa = self.widest_ipa.max(alias.size as u64);
        self.by_physical_start
            .entry(alias.physical_ipa)
            .or_default()
            .push((seq, alias));
        self.by_scope_physical_start
            .entry((alias.ownership_scope, alias.physical_ipa))
            .or_default()
            .push((seq, alias));
        *self
            .physical_size_counts_by_scope
            .entry(alias.ownership_scope)
            .or_default()
            .entry(alias.physical_size as u64)
            .or_default() += 1;
    }

    fn index_remove(&mut self, seq: u64, alias: AliasBacking) {
        if let Some(rows) = self.by_va_start.get_mut(&alias.start) {
            if let Some(at) = rows.iter().position(|row| *row == (seq, alias)) {
                rows.remove(at);
            }
            if rows.is_empty() {
                self.by_va_start.remove(&alias.start);
            }
        }
        if let Some(rows) = self.by_ipa_start.get_mut(&alias.ipa) {
            if let Some(at) = rows.iter().position(|row| *row == (seq, alias)) {
                rows.remove(at);
            }
            if rows.is_empty() {
                self.by_ipa_start.remove(&alias.ipa);
            }
        }
        if let Some(rows) = self.by_physical_start.get_mut(&alias.physical_ipa) {
            if let Some(at) = rows.iter().position(|row| *row == (seq, alias)) {
                rows.remove(at);
            }
            if rows.is_empty() {
                self.by_physical_start.remove(&alias.physical_ipa);
            }
        }
        let physical_key = (alias.ownership_scope, alias.physical_ipa);
        if let Some(rows) = self.by_scope_physical_start.get_mut(&physical_key) {
            if let Some(at) = rows.iter().position(|row| *row == (seq, alias)) {
                rows.remove(at);
            }
            if rows.is_empty() {
                self.by_scope_physical_start.remove(&physical_key);
            }
        }
        if let Some(counts) = self
            .physical_size_counts_by_scope
            .get_mut(&alias.ownership_scope)
        {
            if let Some(count) = counts.get_mut(&(alias.physical_size as u64)) {
                *count = count.saturating_sub(1);
                if *count == 0 {
                    counts.remove(&(alias.physical_size as u64));
                }
            }
            if counts.is_empty() {
                self.physical_size_counts_by_scope
                    .remove(&alias.ownership_scope);
            }
        }
    }

    /// Rebuild all window indexes from the buckets. Used where a registry is
    /// constructed directly rather than through the mutators.
    fn reindex(&mut self) {
        self.by_va_start.clear();
        self.by_ipa_start.clear();
        self.by_physical_start.clear();
        self.by_scope_physical_start.clear();
        self.physical_size_counts_by_scope.clear();
        self.exact_first_by_scope.clear();
        self.widest_va = 0;
        self.widest_ipa = 0;
        let rows: Vec<(u64, AliasBacking)> = self
            .by_scope
            .values()
            .flat_map(|rows| rows.iter().copied())
            .collect();
        for (seq, alias) in rows {
            self.index_insert(seq, alias);
        }
        for scope in self.by_scope.keys().copied().collect::<Vec<_>>() {
            self.rebuild_exact_scope(scope);
        }
    }

    /// The row registered LAST whose window contains `probe`, among the rows
    /// an index keyed by window start holds.
    fn newest_containing(
        index: &std::collections::BTreeMap<u64, Vec<(u64, AliasBacking)>>,
        widest: u64,
        probe: u64,
        mut matches: impl FnMut(&AliasBacking) -> bool,
    ) -> Option<AliasBacking> {
        index
            .range(probe.saturating_sub(widest)..=probe)
            .flat_map(|(_, rows)| rows)
            .filter(|(_, alias)| matches(alias))
            .max_by_key(|(seq, _)| *seq)
            .map(|(_, alias)| *alias)
    }

    /// [`Self::newest_matching`] for a predicate that requires the row's
    /// guest-VA window to contain `va`.
    fn newest_containing_va(
        &self,
        va: u64,
        matches: impl FnMut(&AliasBacking) -> bool,
    ) -> Option<AliasBacking> {
        Self::newest_containing(&self.by_va_start, self.widest_va, va, matches)
    }

    /// [`Self::oldest_matching`] for a predicate that requires the row's IPA
    /// window to contain `ipa`.
    fn oldest_containing_ipa(
        &self,
        ipa: u64,
        mut matches: impl FnMut(&AliasBacking) -> bool,
    ) -> Option<AliasBacking> {
        self.by_ipa_start
            .range(ipa.saturating_sub(self.widest_ipa)..=ipa)
            .flat_map(|(_, rows)| rows)
            .filter(|(_, alias)| matches(alias))
            .min_by_key(|(seq, _)| *seq)
            .map(|(_, alias)| *alias)
    }

    /// [`Self::newest_matching`] for a predicate that requires the row's IPA
    /// window to contain `ipa`.
    fn newest_containing_ipa(
        &self,
        ipa: u64,
        matches: impl FnMut(&AliasBacking) -> bool,
    ) -> Option<AliasBacking> {
        Self::newest_containing(&self.by_ipa_start, self.widest_ipa, ipa, matches)
    }

    /// Private rows owned by one process whose exact physical stage-2 extent
    /// fully contains `[physical_ipa, physical_ipa + physical_len)`.
    ///
    /// The returned rows are candidates only. Callers must authenticate their
    /// host-owner generation before using them as lifetime evidence.
    fn private_owned_containing_physical(
        &self,
        mm_root_slot: Option<(u64, u64)>,
        container_root: ContainerRootToken,
        physical_ipa: u64,
        physical_len: u64,
    ) -> Vec<AliasBacking> {
        let Some(physical_end) = physical_ipa.checked_add(physical_len) else {
            return Vec::new();
        };
        let scope = Self::owned_scope(mm_root_slot, container_root);
        let widest = self
            .physical_size_counts_by_scope
            .get(&scope)
            .and_then(|counts| counts.last_key_value().map(|(&size, _)| size))
            .unwrap_or(0);
        let lower = physical_end.saturating_sub(widest);
        let rows = self
            .by_scope_physical_start
            .range((scope, lower)..=(scope, physical_ipa))
            .flat_map(|(_, rows)| rows);
        let mut candidates = Vec::new();
        for (_, alias) in rows {
            note_alias_state_rows_scanned(1);
            if alias.sharing == GuestMappingSharing::Private
                && alias
                    .physical_ipa
                    .checked_add(alias.physical_size as u64)
                    .is_some_and(|end| physical_end <= end)
            {
                candidates.push(*alias);
            }
        }
        candidates
    }

    fn push(&mut self, alias: AliasBacking) {
        self.bump_revision();
        let seq = self.next_seq;
        self.next_seq = self.next_seq.saturating_add(1);
        let rows = self.by_scope.entry(alias.ownership_scope).or_default();
        let position = rows.len();
        rows.push((seq, alias));
        self.exact_first_by_scope
            .entry(alias.ownership_scope)
            .or_default()
            .entry((alias.start, alias.ipa))
            .or_insert((position, seq, alias));
        self.rows = self.rows.saturating_add(1);
        self.index_insert(seq, alias);
    }

    #[cfg(test)]
    /// Replace every row, in the given order, with fresh sequences.
    fn replace_all(&mut self, aliases: impl IntoIterator<Item = AliasBacking>) {
        self.clear();
        self.extend(aliases);
    }

    #[cfg(test)]
    fn extend(&mut self, aliases: impl IntoIterator<Item = AliasBacking>) {
        for alias in aliases {
            self.push(alias);
        }
    }

    fn clear(&mut self) {
        if self.rows != 0 {
            self.bump_revision();
        }
        self.by_scope.clear();
        self.exact_first_by_scope.clear();
        self.by_va_start.clear();
        self.by_ipa_start.clear();
        self.by_physical_start.clear();
        self.by_scope_physical_start.clear();
        self.physical_size_counts_by_scope.clear();
        self.widest_va = 0;
        self.widest_ipa = 0;
        self.rows = 0;
        // `next_seq` is deliberately NOT reset: sequence numbers are identity
        // for ordering comparisons that may outlive a clear.
    }

    /// Total live rows.
    ///
    /// Summing the buckets makes this O(live processes), and it is read on
    /// every generic mutation; that showed up as `AliasRegistry::len` at 4.2%
    /// of carrier CPU once the bigger scans were gone.
    fn len(&self) -> usize {
        self.rows
    }

    /// Test-only: the total recomputed from the buckets. Production reads the
    /// maintained `rows`; `alias_registry_row_total_tracks_its_buckets` proves
    /// the two agree. Deliberately NOT a `debug_assert` inside `len`, which
    /// would re-sum every bucket in exactly the debug builds the conformance
    /// lane runs — the same mistake the frame-inventory counter made.
    #[cfg(test)]
    fn recomputed_len(&self) -> usize {
        self.by_scope.values().map(Vec::len).sum()
    }

    #[cfg(test)]
    fn is_empty(&self) -> bool {
        self.by_scope.values().all(Vec::is_empty)
    }

    /// Rows of one scope, oldest first.
    fn scope_rows(&self, scope: AliasOwnershipScope) -> &[(u64, AliasBacking)] {
        self.by_scope.get(&scope).map_or(&[], Vec::as_slice)
    }

    /// Rows whose physical stage-2 extent starts exactly at `physical_ipa`.
    /// Owner retirement authenticates length/host/generation separately.
    fn physical_start_rows(&self, physical_ipa: u64) -> &[(u64, AliasBacking)] {
        let rows: &[(u64, AliasBacking)] = self
            .by_physical_start
            .get(&physical_ipa)
            .map_or(&[], Vec::as_slice);
        note_alias_state_rows_scanned(rows.len());
        rows
    }

    /// Every row in GLOBAL insertion order, oldest first. O(n log n); use
    /// [`Self::scope_rows`] when the question is scoped.
    fn ordered(&self) -> Vec<AliasBacking> {
        let mut rows: Vec<(u64, AliasBacking)> = self
            .by_scope
            .values()
            .flat_map(|rows| rows.iter().copied())
            .collect();
        // STABLE: a row split into fragments keeps its parent's sequence,
        // so equal keys must retain their bucket-relative emission order.
        rows.sort_by_key(|(seq, _)| *seq);
        rows.into_iter().map(|(_, alias)| alias).collect()
    }

    /// Every row, in NO meaningful order, borrowed and without allocating.
    ///
    /// Use this only where the answer cannot depend on order: `any`, `min`,
    /// a per-key `find` (all rows for one `(start, ipa, scope)` live in one
    /// scope bucket, so bucket order IS their insertion order), or a whole-registry
    /// predicate. Where the caller takes the first or last match ACROSS keys,
    /// use [`Self::oldest_matching`] / [`Self::newest_matching`] instead:
    /// those answers change with the order, and getting it wrong is silent.
    /// With a thousand processes aliasing one shared futex page at the same
    /// IPA, bucket order handed different processes different `host_addr`s for
    /// the same futex word.
    ///
    /// Materializing global order here instead was measured at 89.6% of all
    /// carrier CPU (`AliasRegistry::ordered`), because these lookups are hot;
    /// the ordering primitives below are single passes with no allocation, so
    /// they cost exactly what the old flat `Vec` scan cost.
    fn iter(&self) -> impl Iterator<Item = &AliasBacking> {
        self.by_scope
            .values()
            .flat_map(|rows| rows.iter().map(|(_, alias)| alias))
    }

    /// The matching row registered FIRST, in global insertion order.
    ///
    /// Superseded on every production path by the window-indexed lookups, and
    /// retained as their ORACLE: `window_indexed_lookups_match_a_full_scan`
    /// asserts the two agree across mutations, because an index that drifts
    /// from its buckets fails silently — which is exactly how the first
    /// partitioning attempt lost `futexforkrequeue`'s futex wakes.
    #[cfg(test)]
    fn oldest_matching(
        &self,
        mut matches: impl FnMut(&AliasBacking) -> bool,
    ) -> Option<AliasBacking> {
        self.by_scope
            .values()
            .flatten()
            .filter(|(_, alias)| matches(alias))
            .min_by_key(|(seq, _)| *seq)
            .map(|(_, alias)| *alias)
    }

    /// The matching row registered LAST, in global insertion order. Oracle
    /// for the window-indexed lookups; see [`Self::oldest_matching`].
    #[cfg(test)]
    fn newest_matching(
        &self,
        mut matches: impl FnMut(&AliasBacking) -> bool,
    ) -> Option<AliasBacking> {
        self.by_scope
            .values()
            .flatten()
            .filter(|(_, alias)| matches(alias))
            .max_by_key(|(seq, _)| *seq)
            .map(|(_, alias)| *alias)
    }

    #[cfg(feature = "foreign-cow-test-support")]
    /// Mutate the row registered LAST among those matching, and report
    /// whether one was found. Selection is identical to
    /// [`Self::newest_matching`]; a row is located by (scope, position)
    /// rather than by sequence because a split row's fragments share their
    /// parent's sequence.
    fn update_newest_matching(
        &mut self,
        mut matches: impl FnMut(&AliasBacking) -> bool,
        update: impl FnOnce(&mut AliasBacking),
    ) -> bool {
        let mut best: Option<(AliasOwnershipScope, usize, u64)> = None;
        for (scope, rows) in &self.by_scope {
            for (position, (seq, alias)) in rows.iter().enumerate() {
                if matches(alias) && best.is_none_or(|(_, _, best_seq)| *seq >= best_seq) {
                    best = Some((*scope, position, *seq));
                }
            }
        }
        let Some((scope, position, _)) = best else {
            return false;
        };
        let Some(rows) = self.by_scope.get_mut(&scope) else {
            return false;
        };
        let Some(slot) = rows.get_mut(position) else {
            return false;
        };
        let seq = slot.0;
        let previous = slot.1;
        update(&mut slot.1);
        let updated = slot.1;
        if updated != previous {
            self.bump_revision();
        }
        self.index_remove(seq, previous);
        self.index_insert(seq, updated);
        self.rebuild_exact_scope(scope);
        true
    }

    /// [`Self::newest_matching`] restricted to the scopes one process can see.
    /// Exact for any predicate that already required
    /// `alias_matches_process_scope`, and O(that process's rows) rather than
    /// O(carrier).
    fn newest_matching_for_process(
        &self,
        mm_root_slot: Option<(u64, u64)>,
        container_root: ContainerRootToken,
        mut matches: impl FnMut(&AliasBacking) -> bool,
    ) -> Option<AliasBacking> {
        Self::process_visible_scopes(mm_root_slot, container_root)
            .into_iter()
            .flat_map(|scope| self.scope_rows(scope))
            .filter(|(_, alias)| matches(alias))
            .max_by_key(|(seq, _)| *seq)
            .map(|(_, alias)| *alias)
    }

    #[cfg(test)]
    fn contains(&self, alias: &AliasBacking) -> bool {
        self.scope_rows(alias.ownership_scope)
            .iter()
            .any(|(_, row)| row == alias)
    }

    #[allow(dead_code)]
    fn retain(&mut self, mut keep: impl FnMut(&AliasBacking) -> bool) {
        let mut dropped = Vec::new();
        let scopes = self.by_scope.keys().copied().collect::<Vec<_>>();
        for scope in scopes {
            let Some(rows) = self.by_scope.get_mut(&scope) else {
                continue;
            };
            rows.retain(|row| {
                let survives = keep(&row.1);
                if !survives {
                    dropped.push(*row);
                }
                survives
            });
            self.rebuild_exact_scope(scope);
        }
        self.rows = self.rows.saturating_sub(dropped.len());
        if !dropped.is_empty() {
            self.bump_revision();
        }
        for (seq, alias) in dropped {
            self.index_remove(seq, alias);
        }
        self.by_scope.retain(|_, rows| !rows.is_empty());
    }

    /// Remove every row of one scope and return them, oldest first. This is
    /// the process-retirement primitive: O(that scope's rows), not O(carrier).
    fn remove_scope(&mut self, scope: AliasOwnershipScope) -> Vec<AliasBacking> {
        let Some(rows) = self.by_scope.remove(&scope) else {
            return Vec::new();
        };
        self.exact_first_by_scope.remove(&scope);
        self.bump_revision();
        self.rows = self.rows.saturating_sub(rows.len());
        for &(seq, alias) in &rows {
            self.index_remove(seq, alias);
        }
        rows.into_iter().map(|(_, alias)| alias).collect()
    }

    /// Retain within one scope, returning the removed rows oldest first.
    fn retain_in_scope(
        &mut self,
        scope: AliasOwnershipScope,
        mut keep: impl FnMut(&AliasBacking) -> bool,
    ) -> Vec<AliasBacking> {
        let mut dropped = Vec::new();
        if let Some(rows) = self.by_scope.get_mut(&scope) {
            rows.retain(|row| {
                let survives = keep(&row.1);
                if !survives {
                    dropped.push(*row);
                }
                survives
            });
            self.rows = self.rows.saturating_sub(dropped.len());
            if rows.is_empty() {
                self.by_scope.remove(&scope);
            }
        }
        for &(seq, alias) in &dropped {
            self.index_remove(seq, alias);
        }
        if !dropped.is_empty() {
            self.bump_revision();
        }
        self.rebuild_exact_scope(scope);
        dropped.into_iter().map(|(_, alias)| alias).collect()
    }

    /// Rebuild one scope's rows, sequences included, keeping the row total
    /// exact. A VA unmap splits rows into fragments that must inherit their
    /// parent's sequence, so the caller needs the sequences, not just the
    /// aliases.
    fn rebuild_scope_rows(
        &mut self,
        scope: AliasOwnershipScope,
        rebuild: impl FnOnce(Vec<(u64, AliasBacking)>) -> Vec<(u64, AliasBacking)>,
    ) {
        let Some(previous) = self.by_scope.get_mut(&scope).map(std::mem::take) else {
            return;
        };
        let before = previous.len();
        let replacement = rebuild(previous.clone());
        if replacement != previous {
            self.bump_revision();
        }
        self.rows = self
            .rows
            .saturating_sub(before)
            .saturating_add(replacement.len());
        *self
            .by_scope
            .get_mut(&scope)
            .unwrap_or_else(|| std::process::abort()) = replacement.clone();
        for (seq, alias) in previous {
            self.index_remove(seq, alias);
        }
        for (seq, alias) in replacement {
            self.index_insert(seq, alias);
        }
        self.rebuild_exact_scope(scope);
        self.drop_empty_scope(scope);
    }

    fn drop_empty_scope(&mut self, scope: AliasOwnershipScope) {
        if self.by_scope.get(&scope).is_some_and(Vec::is_empty) {
            self.by_scope.remove(&scope);
        }
    }

    /// The FIRST row registered for one exact semantic alias identity.
    ///
    /// Every row of one scope lives in one bucket in insertion order, so the
    /// first match in that bucket IS the first match in global insertion
    /// order — the answer the historical whole-registry `find` gave, without
    /// visiting any other process's rows.
    fn find_by_key(
        &self,
        start: u64,
        ipa: u64,
        scope: AliasOwnershipScope,
    ) -> Option<AliasBacking> {
        let found = self
            .exact_first_by_scope
            .get(&scope)
            .and_then(|exact| exact.get(&(start, ipa)))
            .map(|(_, _, entry)| *entry);
        note_alias_state_rows_scanned(usize::from(found.is_some()));
        found
    }

    /// Replace the first row for `alias`'s `(start, ipa, scope)`, or append it,
    /// and report the row that was replaced.
    /// Same first-occurrence semantics as [`Self::find_by_key`]; a replaced
    /// row keeps its sequence, so it keeps its place in the global order
    /// exactly as an in-place `Vec` write did.
    fn upsert_by_key(&mut self, alias: AliasBacking) -> Option<AliasBacking> {
        let scope = alias.ownership_scope;
        let exact = self
            .exact_first_by_scope
            .get(&scope)
            .and_then(|rows| rows.get(&(alias.start, alias.ipa)))
            .copied();
        if let Some((position, seq, previous)) = exact {
            note_alias_state_rows_scanned(1);
            let slot = self
                .by_scope
                .get_mut(&scope)
                .and_then(|rows| rows.get_mut(position))
                .unwrap_or_else(|| std::process::abort());
            if slot.0 != seq || slot.1 != previous {
                std::process::abort();
            }
            slot.1 = alias;
            if previous != alias {
                self.bump_revision();
            }
            self.index_remove(seq, previous);
            self.index_insert(seq, alias);
            self.exact_first_by_scope
                .get_mut(&scope)
                .and_then(|rows| rows.get_mut(&(alias.start, alias.ipa)))
                .unwrap_or_else(|| std::process::abort())
                .2 = alias;
            return Some(previous);
        }
        self.push(alias);
        None
    }

    /// Replace several exact semantic keys with one scan per affected scope.
    /// Values are appended in slice order, preserving the historical
    /// retirement behavior where a restored preimage receives a fresh global
    /// sequence after the rows that survived.
    fn replace_exact_keys_in_batch(
        &mut self,
        replacements: &[(AliasVersionKey, Option<AliasBacking>)],
    ) {
        let mut keys_by_scope = std::collections::BTreeMap::<
            AliasOwnershipScope,
            std::collections::BTreeSet<(u64, u64)>,
        >::new();
        for &((start, ipa, scope), replacement) in replacements {
            if let Some(replacement) = replacement
                && alias_version_key(&replacement) != (start, ipa, scope)
            {
                std::process::abort();
            }
            keys_by_scope.entry(scope).or_default().insert((start, ipa));
        }
        for (scope, keys) in keys_by_scope {
            self.rebuild_scope_rows(scope, |rows| {
                note_alias_state_rows_scanned(rows.len());
                rows.into_iter()
                    .filter(|(_, alias)| !keys.contains(&(alias.start, alias.ipa)))
                    .collect()
            });
        }
        for &(_, replacement) in replacements {
            if let Some(alias) = replacement {
                self.push(alias);
            }
        }
    }

    /// Remove only values captured from an older semantic publication. A
    /// delayed exec cleanup must not interpret `(VA, IPA, scope)` as immutable:
    /// an exec successor can reuse all three while carrying a new physical
    /// owner generation. Each affected scope is rebuilt once, so retiring k
    /// captured rows remains O(rows-in-scope + k log k), not O(k * rows).
    fn remove_exact_values_in_batch(&mut self, expected: &[AliasBacking]) -> Vec<AliasBacking> {
        let mut expected_by_scope = std::collections::BTreeMap::<
            AliasOwnershipScope,
            std::collections::BTreeMap<(u64, u64), Vec<AliasBacking>>,
        >::new();
        for &alias in expected {
            expected_by_scope
                .entry(alias.ownership_scope)
                .or_default()
                .entry((alias.start, alias.ipa))
                .or_default()
                .push(alias);
        }
        let mut removed = Vec::new();
        for (scope, expected_by_key) in expected_by_scope {
            self.rebuild_scope_rows(scope, |rows| {
                note_alias_state_rows_scanned(rows.len());
                rows.into_iter()
                    .filter(|(_, alias)| {
                        let retires = expected_by_key
                            .get(&(alias.start, alias.ipa))
                            .is_some_and(|expected| expected.contains(alias));
                        if retires {
                            removed.push(*alias);
                        }
                        !retires
                    })
                    .collect()
            });
        }
        removed
    }

    /// Every row one process can see, in global insertion order.
    ///
    /// The fork paths materialized the WHOLE carrier registry and then
    /// filtered it by scope, which is O(all processes) per fork plus a sort
    /// and an allocation. Every consumer of that vector re-applies
    /// `alias_matches_process_scope`, so restricting it here is exact.
    fn process_visible_ordered(
        &self,
        mm_root_slot: Option<(u64, u64)>,
        container_root: ContainerRootToken,
    ) -> Vec<AliasBacking> {
        let mut rows: Vec<(u64, AliasBacking)> =
            Self::process_visible_scopes(mm_root_slot, container_root)
                .into_iter()
                .flat_map(|scope| self.scope_rows(scope).iter().copied())
                .collect();
        note_alias_state_rows_scanned(rows.len());
        rows.sort_by_key(|(seq, _)| *seq);
        rows.into_iter().map(|(_, alias)| alias).collect()
    }

    /// A registry holding only the rows one process can see, sequences and
    /// order preserved. Every caller that plans a mutation against a private
    /// copy is scope-filtered anyway, so cloning the whole carrier-global
    /// registry per `munmap` was pure per-process tax.
    fn process_visible_snapshot(
        &self,
        mm_root_slot: Option<(u64, u64)>,
        container_root: ContainerRootToken,
    ) -> Self {
        let mut snapshot = Self {
            next_seq: self.next_seq,
            ..Self::default()
        };
        for scope in Self::process_visible_scopes(mm_root_slot, container_root) {
            if let Some(rows) = self.by_scope.get(&scope) {
                snapshot.rows = snapshot.rows.saturating_add(rows.len());
                snapshot.by_scope.insert(scope, rows.clone());
            }
        }
        snapshot.reindex();
        snapshot
    }

    /// The two scopes a process can see, per `alias_matches_process_scope`:
    /// the one it owns, plus the shared-file `Global` namespace.
    fn process_visible_scopes(
        mm_root_slot: Option<(u64, u64)>,
        container_root: ContainerRootToken,
    ) -> [AliasOwnershipScope; 2] {
        [
            Self::owned_scope(mm_root_slot, container_root),
            AliasOwnershipScope::Global,
        ]
    }

    /// The scope a process owns, per `alias_is_owned_by_process`.
    fn owned_scope(
        mm_root_slot: Option<(u64, u64)>,
        container_root: ContainerRootToken,
    ) -> AliasOwnershipScope {
        match mm_root_slot {
            Some((base, size)) => AliasOwnershipScope::MmRootSlot { base, size },
            None => AliasOwnershipScope::ContainerRoot(container_root),
        }
    }
}

#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
#[derive(Debug, Clone)]
pub(crate) enum GlobalFrameOwnerEntry {
    Live(std::sync::Arc<GlobalFrameHostOwner>),
    RetirementPending {
        owner: std::sync::Arc<GlobalFrameHostOwner>,
        #[allow(dead_code)]
        error: Option<String>,
        in_flight: bool,
    },
}

#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
impl GlobalFrameOwnerEntry {
    pub(crate) fn owner(&self) -> &std::sync::Arc<GlobalFrameHostOwner> {
        match self {
            Self::Live(owner) | Self::RetirementPending { owner, .. } => owner,
        }
    }

    fn live_owner(&self) -> Option<&std::sync::Arc<GlobalFrameHostOwner>> {
        match self {
            Self::Live(owner) => Some(owner),
            Self::RetirementPending { .. } => None,
        }
    }

    fn is_live_exact(&self, expected: &std::sync::Arc<GlobalFrameHostOwner>) -> bool {
        self.live_owner()
            .is_some_and(|owner| std::sync::Arc::ptr_eq(owner, expected))
    }

    #[allow(dead_code)]
    pub(crate) fn is_live(&self) -> bool {
        matches!(self, Self::Live(_))
    }

    #[allow(dead_code)]
    pub(crate) fn is_pending(&self) -> bool {
        matches!(self, Self::RetirementPending { .. })
    }
}

/// Carrier-scoped ownership of host mappings installed at reusable global frame
/// IPAs. Per-vCPU mapping rows are non-owning views; otherwise the vCPU that
/// happened to service `mmap` would pin the host extent until process exit even
/// after another thread completed the final `munmap`.
#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
#[derive(Debug)]
struct GlobalFrameSharedMapping {
    mapping: crate::host_mapping::OwnedHostMapping,
    logical_pin_count: parking_lot::Mutex<u64>,
}

#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
impl GlobalFrameSharedMapping {
    fn new(mapping: crate::host_mapping::OwnedHostMapping) -> Self {
        Self {
            mapping,
            logical_pin_count: parking_lot::Mutex::new(0),
        }
    }

    fn pin(&self) -> Result<(), CarrierStage2PinError> {
        let mut count = self.logical_pin_count.lock();
        *count = count
            .checked_add(1)
            .ok_or(CarrierStage2PinError::PinCountExhausted)?;
        Ok(())
    }

    fn unpin(&self) {
        let mut count = self.logical_pin_count.lock();
        *count = count.saturating_sub(1);
    }

    fn pin_count(&self) -> u64 {
        *self.logical_pin_count.lock()
    }
}

// SAFETY: this mapping is immutable after publication. Its process address is
// stable, reads are guarded by typed custody pins, and only explicit terminal
// custody retirement can drop the final shared owner.
#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
unsafe impl Send for GlobalFrameSharedMapping {}

// SAFETY: see the Send argument above; concurrent users only read/copy bytes
// from the stable MAP_SHARED extent.
#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
unsafe impl Sync for GlobalFrameSharedMapping {}

#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
#[derive(Debug)]
pub(crate) struct GlobalFrameHostOwner {
    mapping: std::sync::Arc<GlobalFrameSharedMapping>,
    custody: std::sync::Weak<CarrierVmCustody>,
    record_identity: CarrierStage2RecordIdentity,
}

#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
impl GlobalFrameHostOwner {
    fn from_record(
        mapping: std::sync::Arc<GlobalFrameSharedMapping>,
        custody: std::sync::Arc<CarrierVmCustody>,
        record_identity: CarrierStage2RecordIdentity,
    ) -> Self {
        Self {
            mapping,
            custody: std::sync::Arc::downgrade(&custody),
            record_identity,
        }
    }

    #[cfg(test)]
    pub(crate) fn new(
        mut lease: GlobalFrameStage2Lease,
        mapping: crate::host_mapping::OwnedHostMapping,
        perms: u64,
        generation: u64,
        ipa: u64,
        length: u64,
    ) -> Self {
        if !lease.mapped {
            lease.mark_test_mapped_without_backend();
        }
        let custody = std::sync::Arc::clone(legacy_test_carrier_vm_custody_arc());
        let identity = transfer_global_frame_stage2_lease_to_custody(
            &custody,
            lease,
            mapping.as_ptr() as usize,
            perms,
            Some(CarrierLogicalOwner {
                id: generation,
                generation,
            }),
        )
        .unwrap_or_else(|error| panic!("register test global owner record: {error}"));
        assert_eq!(
            custody
                .stage2_record_snapshot(identity.record_id)
                .map(|snapshot| (snapshot.ipa, snapshot.len as u64)),
            Some((ipa, length))
        );
        Self::from_record(
            std::sync::Arc::new(GlobalFrameSharedMapping::new(mapping)),
            custody,
            identity,
        )
    }

    fn snapshot(&self) -> Option<CarrierStage2RecordSnapshot> {
        self.custody
            .upgrade()?
            .stage2_record_snapshot(self.record_identity.record_id)
    }

    fn pin(self: &std::sync::Arc<Self>) -> Result<GlobalFrameOwnerPin, CarrierStage2PinError> {
        let custody = self
            .custody
            .upgrade()
            .ok_or(CarrierStage2PinError::NotFound)?;
        let stage2_pin = custody.pin_stage2_record(self.record_identity)?;
        self.mapping.pin()?;
        Ok(GlobalFrameOwnerPin {
            owner: std::sync::Arc::clone(self),
            _stage2_pin: stage2_pin,
        })
    }

    pub(crate) fn host_addr(&self) -> usize {
        self.mapping.mapping.as_ptr() as usize
    }

    pub(crate) fn generation(&self) -> u64 {
        self.record_identity
            .logical_owner
            .map_or(0, |owner| owner.generation)
    }

    #[allow(dead_code)]
    pub(crate) fn ipa(&self) -> u64 {
        self.snapshot().map_or(0, |snapshot| snapshot.ipa)
    }

    pub(crate) fn length(&self) -> u64 {
        self.mapping.mapping.len() as u64
    }

    pub(crate) fn perms(&self) -> u64 {
        self.snapshot().map_or(0, |snapshot| snapshot.perms)
    }

    pub(crate) fn ptr(&self) -> *mut u8 {
        self.mapping.mapping.as_ptr()
    }

    pub(crate) fn as_ptr(&self) -> *mut u8 {
        self.ptr()
    }

    pub(crate) fn len(&self) -> usize {
        self.mapping.mapping.len()
    }

    #[allow(dead_code)]
    pub(crate) fn is_retired(&self) -> bool {
        self.snapshot()
            .is_none_or(|snapshot| !snapshot.mapped || snapshot.terminalized_by_vm_destroy)
    }

    pub(crate) fn lease_fingerprint(&self) -> Option<ExecLeaseFingerprint> {
        self.snapshot().map(|snapshot| ExecLeaseFingerprint {
            base: snapshot.ipa,
            length: snapshot.len as u64,
            mapped: snapshot.mapped,
            active: !snapshot.terminalized_by_vm_destroy,
            release_ipa: snapshot.release_ipa,
        })
    }

    #[cfg(test)]
    fn try_retire(&self) -> Result<(), TrapError> {
        let custody = self.custody.upgrade().ok_or_else(|| {
            TrapError::Hypervisor("global owner carrier custody disappeared".to_owned())
        })?;
        match custody
            .retire_stage2_record_using(self.record_identity, unmap_global_frame_stage2_record)
        {
            CarrierStage2RetireOutcome::RetiredUnmapped
            | CarrierStage2RetireOutcome::TerminalizedByVmDestroy => {
                finalize_global_frame_owner_record(&custody, self)
            }
            CarrierStage2RetireOutcome::DeferredActivePins => Err(TrapError::Hypervisor(
                "global owner retirement deferred by active pins".to_owned(),
            )),
            CarrierStage2RetireOutcome::RetryPending(error) => Err(TrapError::Hypervisor(format!(
                "global owner retirement retry pending: {error:?}"
            ))),
            outcome => Err(TrapError::Hypervisor(format!(
                "global owner retirement identity failure: {outcome:?}"
            ))),
        }
    }
}

#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
#[derive(Debug)]
pub(crate) struct GlobalFrameOwnerPin {
    owner: std::sync::Arc<GlobalFrameHostOwner>,
    _stage2_pin: CarrierStage2Pin,
}

#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
impl GlobalFrameOwnerPin {
    fn owner(&self) -> &GlobalFrameHostOwner {
        &self.owner
    }
}

#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
#[derive(Debug)]
pub(crate) struct PhysicalCowSource {
    host_addr: *mut u8,
    physical_ipa: u64,
    _owner_pin: Option<GlobalFrameOwnerPin>,
}

#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
impl PhysicalCowSource {
    fn unpinned(host_addr: *mut u8, physical_ipa: u64) -> Self {
        Self {
            host_addr,
            physical_ipa,
            _owner_pin: None,
        }
    }

    fn pinned(pin: GlobalFrameOwnerPin, offset: usize, physical_ipa: u64) -> Self {
        let host_addr = unsafe { pin.owner().as_ptr().add(offset) };
        Self {
            host_addr,
            physical_ipa,
            _owner_pin: Some(pin),
        }
    }

    fn host_addr(&self) -> *mut u8 {
        self.host_addr
    }

    fn physical_ipa(&self) -> u64 {
        self.physical_ipa
    }
}

#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
impl Drop for GlobalFrameOwnerPin {
    fn drop(&mut self) {
        self.owner.mapping.unpin();
    }
}

#[cfg(all(test, target_os = "macos", target_arch = "aarch64"))]
fn next_global_frame_owner_generation() -> u64 {
    legacy_test_carrier_vm_custody()
        .allocate_logical_owner()
        .map_or(0, |owner| owner.generation)
}

/// The live owner generation for `(ipa, length)`, or 0 when unowned.
///
/// Rows stamp this at publication, which always happens while the lease is
/// live, so a row records the incarnation it was actually published against.
#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
fn global_frame_host_owner_generation_in(custody: &CarrierVmCustody, ipa: u64, length: u64) -> u64 {
    global_frame_host_owner_identity_in(custody, ipa, length)
        .map_or(0, |(_, generation)| generation)
}

/// The exact host pointer and generation currently owning a reusable extent.
///
/// Retirement diagnostics and inventory authentication need the complete
/// identity. A generation or a recycled host pointer alone is insufficient.
#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
fn global_frame_host_owner_identity_in(
    custody: &CarrierVmCustody,
    ipa: u64,
    length: u64,
) -> Option<(usize, u64)> {
    custody
        .global_frame_host_owners
        .lock()
        .get(&(ipa, length))
        .and_then(|entry| match entry {
            GlobalFrameOwnerEntry::Live(owner) => Some((owner.host_addr(), owner.generation())),
            GlobalFrameOwnerEntry::RetirementPending { .. } => None,
        })
}

#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
fn pin_exact_live_global_frame_owner_in(
    custody: &CarrierVmCustody,
    ipa: u64,
    length: u64,
    expected_host_addr: usize,
    expected_generation: u64,
) -> Option<GlobalFrameOwnerPin> {
    if expected_generation == 0 {
        return None;
    }
    let owner = custody
        .global_frame_host_owners
        .lock()
        .get(&(ipa, length))
        .and_then(GlobalFrameOwnerEntry::live_owner)
        .filter(|owner| {
            owner.host_addr() == expected_host_addr && owner.generation() == expected_generation
        })
        .cloned()?;
    let pin = owner.pin().ok()?;
    let still_current = custody
        .global_frame_host_owners
        .lock()
        .get(&(ipa, length))
        .is_some_and(|entry| entry.is_live_exact(&owner));
    still_current.then_some(pin)
}

#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
fn global_frame_owner_is_replayable_in(
    custody: &CarrierVmCustody,
    ipa: u64,
    length: u64,
    host_addr: usize,
    generation: u64,
) -> bool {
    match custody.global_frame_host_owners.lock().get(&(ipa, length)) {
        Some(GlobalFrameOwnerEntry::Live(owner)) => {
            owner.host_addr() == host_addr && (generation == 0 || owner.generation() == generation)
        }
        Some(GlobalFrameOwnerEntry::RetirementPending { .. }) => false,
        None => generation == 0,
    }
}

// SAFETY: the mapping is process-address-space state. Its address is stable,
// HVF and guest-memory access already cross host threads, and explicit custody
// retirement serializes stage-2 unmap before the final owning Arc is removed.
#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
unsafe impl Send for GlobalFrameHostOwner {}

// SAFETY: all owner fields are immutable after publication. Reads hold a typed
// custody pin for the exact record, and retirement cannot remove the backing
// until every such pin is released.
#[cfg(all(target_os = "macos", target_arch = "aarch64"))]
unsafe impl Sync for GlobalFrameHostOwner {}

